{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Abemaciclib, a piperazine-containing heteroaromatic kinase inhibitor, has an absolute oral bioavailability of 45% in humans, supporting high F for the query's similar piperazine-heteroaryl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Baricitinib, a heteroaromatic kinase inhibitor with a basic amine, has an absolute oral bioavailability of about 80% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ruxolitinib, a pyrrolopyrimidine kinase inhibitor, has an absolute oral bioavailability of 74% (with some reports >95%), supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Upadacitinib, a tricyclic heteroaromatic kinase inhibitor, has an oral bioavailability of approximately 79%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Belumosudil, an indole-containing kinase inhibitor, has an absolute bioavailability of 64%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Navoximod, an indole-fused heteroaromatic compound, has an absolute bioavailability of 55.5%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Pindolol, an indole with an isopropylamine side chain, has high oral bioavailability (79.5–87%), supporting high F for the isopropyl-piperazine indole-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "SRT2104, a lipophilic heteroaromatic with amide/thiazole/morpholine features, has an absolute bioavailability of 13.8%, below the 20% threshold; its structural differences lower transferability, but it is contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Lisofylline, a urea-linked indazole, has an oral bioavailability of 5.9%, below the threshold; it is structurally distant from the query but provides contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's basic piperazine and heteroaromatic scaffold resembles multiple kinase inhibitors with measured absolute oral bioavailability of 45–80%, all clearly above the 20% threshold. The low-bioavailability analogues are structurally more distant and contain amide/urea/thiazole liabilities not present in the query. Therefore, high oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct experimental pharmacokinetic data are available for the query molecule.",
    "Morgan similarities to all evidence molecules are low, limiting quantitative transferability.",
    "No query-specific data on solubility, permeability, efflux, or first-pass metabolism are available.",
    "The basic piperazine ionization may reduce permeability, but its net effect on F is not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

